-- Generated by backend/scripts/catalog-seed.mjs. Google Books metadata only.
-- Selected books: 60/60. Existing catalog records and personal data are preserved.
BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE books, authors, author_name, categories, category_name, book_author, book_category IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE lb_seed_books (google_id text PRIMARY KEY, info jsonb) ON COMMIT DROP;
DELETE FROM lb_seed_books s WHERE EXISTS (SELECT 1 FROM books b WHERE b.google_books_id = s.google_id);
CREATE TEMP TABLE lb_seed_authors_raw (google_id text, name text, normalized text) ON COMMIT DROP;
CREATE TEMP TABLE lb_seed_authors ON COMMIT DROP AS
SELECT n.normalized, MIN(n.name) AS name,
       COALESCE((SELECT existing.author_id FROM author_name existing WHERE existing.normalized_name = n.normalized), nextval(pg_get_serial_sequence('authors', 'id'))) AS entity_id,
       NOT EXISTS (SELECT 1 FROM author_name e WHERE e.normalized_name = n.normalized) AS is_new
FROM lb_seed_authors_raw n JOIN lb_seed_books b ON b.google_id = n.google_id GROUP BY n.normalized;
SELECT name, normalized, true, entity_id FROM lb_seed_authors s WHERE NOT EXISTS (SELECT 1 FROM author_name e WHERE e.normalized_name = s.normalized);
CREATE TEMP TABLE lb_seed_categories_raw (google_id text, name text, normalized text) ON COMMIT DROP;
CREATE TEMP TABLE lb_seed_categories ON COMMIT DROP AS
SELECT n.normalized, MIN(n.name) AS name,
       COALESCE((SELECT existing.category_id FROM category_name existing WHERE existing.normalized_name = n.normalized), nextval(pg_get_serial_sequence('categories', 'id'))) AS entity_id,
       NOT EXISTS (SELECT 1 FROM category_name e WHERE e.normalized_name = n.normalized) AS is_new
FROM lb_seed_categories_raw n JOIN lb_seed_books b ON b.google_id = n.google_id GROUP BY n.normalized;
SELECT name, normalized, true, entity_id FROM lb_seed_categories s WHERE NOT EXISTS (SELECT 1 FROM category_name e WHERE e.normalized_name = s.normalized);
SELECT google_id, info->>'title', info->>'subtitle', info->>'description', info->>'publisher', info->>'publishedDate',
CASE WHEN left(info->>'publishedDate',4) ~ '^[0-9]{4}$' THEN left(info->>'publishedDate',4)::integer ELSE NULL END,
COALESCE(info#>>'{imageLinks,extraLarge}',info#>>'{imageLinks,large}',info#>>'{imageLinks,medium}',info#>>'{imageLinks,small}',info#>>'{imageLinks,thumbnail}'),
COALESCE(info#>>'{imageLinks,thumbnail}',info#>>'{imageLinks,smallThumbnail}'), (info->>'pageCount')::integer, info->>'language',
COALESCE((SELECT value->>'identifier' FROM jsonb_array_elements(info->'industryIdentifiers') WHERE value->>'type'='ISBN_13' LIMIT 1),(SELECT value->>'identifier' FROM jsonb_array_elements(info->'industryIdentifiers') WHERE value->>'type'='ISBN_10' LIMIT 1)),
CASE WHEN upper(info->>'maturityRating') IN ('MATURE','NOT_MATURE') THEN upper(info->>'maturityRating') ELSE 'NOT_MATURE' END, CURRENT_TIMESTAMP
FROM lb_seed_books;
SELECT DISTINCT b.id, n.entity_id FROM lb_seed_authors_raw r JOIN lb_seed_books s ON s.google_id = r.google_id JOIN books b ON b.google_books_id = r.google_id JOIN lb_seed_authors n ON n.normalized = r.normalized;
SELECT DISTINCT b.id, n.entity_id FROM lb_seed_categories_raw r JOIN lb_seed_books s ON s.google_id = r.google_id JOIN books b ON b.google_books_id = r.google_id JOIN lb_seed_categories n ON n.normalized = r.normalized;
COMMIT;
