('bxEsAAAAMAAJ', '{"title":"Thomas Hardy, a Biography","authors":["Michael Millgate"],"publisher":"New York : Random House","publishedDate":"1982","description":"A comprehensive account of the author''s life based upon many previously unknown materials.","industryIdentifiers":[{"type":"OTHER","identifier":"UOM:39015005029015"}],"readingModes":{"text":false,"image":false},"pageCount":704,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.8.6.0.preview.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=bxEsAAAAMAAJ&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=bxEsAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=bxEsAAAAMAAJ&q=biography&dq=biography&hl=&as_pt=BOOKS&cd=17&source=gbs_api","infoLink":"http://books.google.com.br/books?id=bxEsAAAAMAAJ&dq=biography&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Thomas_Hardy_a_Biography.html?hl=&id=bxEsAAAAMAAJ"}'),
('pghYQGLDMn0C', '{"title":"Bernini''s Biographies","subtitle":"Critical Essays","authors":["Maarten Delbeke","Evonne Anita Levy","Steven F. Ostrow"],"publisher":"Penn State Press","publishedDate":"2006","description":"Unique among early modern artists, the Baroque painter, sculptor, and architect Gianlorenzo Bernini was the subject of two monographic biographies published shortly after his death in 1680: one by the Florentine connoisseur and writer Filippo Baldinucci (1682), and the second by Bernini''s son, Domenico (1713). This interdisciplinary collection of essays by historians of art and literature marks the first sustained examination of the two biographies, first and foremost as texts. A substantial introductory essay considers each biography''s author, genesis, and foundational role in the study of Bernini. Nine essays combining art-historical research with insights from philology, literary history, and art and literary theory offer major new insights into the multifarious connections between biography, art history, and aesthetics, inviting readers to rethink Bernini''s life, art, and milieu. Contributors are Eraldo Bellini, Heiko Damm, John D. Lyons, Sarah McPhee, Tomaso Montanari, Rudolf Preimesberger, Robert Williams, and the editors.Maarten Delbeke is Assistant Professor of architectural history and theory at the universities of Ghent and Leiden. Formerly the Scott Opler Fellow in Architectural History at Worcester College (Oxford), he is the author of several articles and a forthcoming book on Seicento art and theory.Evonne Levy is Associate Professor of the History of Art at the University of Toronto. She is also the author of Propaganda and the Jesuit Baroque (2004).","industryIdentifiers":[{"type":"ISBN_13","identifier":"9780271029016"},{"type":"ISBN_10","identifier":"0271029013"}],"readingModes":{"text":true,"image":true},"pageCount":440,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.7.6.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=pghYQGLDMn0C&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=pghYQGLDMn0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=pghYQGLDMn0C&pg=PA5&dq=biographies&hl=&as_pt=BOOKS&cd=1&source=gbs_api","infoLink":"http://books.google.com.br/books?id=pghYQGLDMn0C&dq=biographies&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Bernini_s_Biographies.html?hl=&id=pghYQGLDMn0C"}'),
('bsZBAQAAMAAJ', '{"title":"Selected List of the Best Biographies in English from the Point of View of a Canadian Public Library","authors":["Ottawa Public Library"],"publishedDate":"1918","industryIdentifiers":[{"type":"OTHER","identifier":"OSU:32435010291870"}],"readingModes":{"text":false,"image":false},"pageCount":84,"printType":"BOOK","categories":["Biography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.5.6.0.preview.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=bsZBAQAAMAAJ&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=bsZBAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=bsZBAQAAMAAJ&q=biographies&dq=biographies&hl=&as_pt=BOOKS&cd=15&source=gbs_api","infoLink":"http://books.google.com.br/books?id=bsZBAQAAMAAJ&dq=biographies&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Selected_List_of_the_Best_Biographies_in.html?hl=&id=bsZBAQAAMAAJ"}'),
('oXvZsxlvEoQC', '{"title":"Autobiographics","subtitle":"A Feminist Theory of Women''s Self-representation","authors":["Leigh Gilmore"],"publisher":"Cornell University Press","publishedDate":"1994","description":"In the first comprehensive feminist critique of autobiography as a genre, Leigh Gilmore incorporates writings that have not up to now been considered part of the autobiographical tradition. Offering subtle and perceptive readings of a wide variety of texts-- from the confessions of medieval mystics to contemporary works by Chicana and lesbian writers-- she identifies an innovative practice of \"autobiographics\" which covers the entire spectrum of women''s self-representation.","industryIdentifiers":[{"type":"ISBN_10","identifier":"0801480612"},{"type":"ISBN_13","identifier":"9780801480614"}],"readingModes":{"text":false,"image":false},"pageCount":284,"printType":"BOOK","categories":["Biography & Autobiography"],"averageRating":5,"ratingsCount":1,"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.9.8.0.preview.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=oXvZsxlvEoQC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=oXvZsxlvEoQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=oXvZsxlvEoQC&pg=PA21&dq=autobiography&hl=&as_pt=BOOKS&cd=11&source=gbs_api","infoLink":"http://books.google.com.br/books?id=oXvZsxlvEoQC&dq=autobiography&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Autobiographics.html?hl=&id=oXvZsxlvEoQC"}'),
('kTswgGNBFBAC', '{"title":"The Memoirs of Count Witte","authors":["Sidney Harcave"],"publisher":"M.E. Sharpe","publishedDate":"1990-10-22","description":"An account of the later years of Tsarism. Witte presents portraits of the statesmen around him, explains the problem of bringing the economy to a level commensurate with Russia''s putative position as the greatest land power in the world and the effort to create a constitutional monarchy.","industryIdentifiers":[{"type":"ISBN_10","identifier":"0765640678"},{"type":"ISBN_13","identifier":"9780765640673"}],"readingModes":{"text":false,"image":true},"pageCount":936,"printType":"BOOK","categories":["Biography & Autobiography"],"averageRating":5,"ratingsCount":1,"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"3.5.4.0.preview.1","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=kTswgGNBFBAC&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=kTswgGNBFBAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=kTswgGNBFBAC&pg=PR18&dq=memoirs&hl=&as_pt=BOOKS&cd=7&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=kTswgGNBFBAC&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=kTswgGNBFBAC"}'),
('5ZopBQAAQBAJ', '{"title":"Becoming Steve Jobs","subtitle":"The evolution of a reckless upstart into a visionary leader","authors":["Brent Schlender","Rick Tetzeli"],"publisher":"Hachette UK","publishedDate":"2015-03-24","description":"THE SUNDAY TIMES AND #1 INTERNATIONAL BESTSELLER - with a new foreword by Silicon Valley legend Marc Andreessen. ''For my money, a better book about Jobs than Walter Isaacson''s biography'' New Yorker ''A fascinating reinterpretation of the Steve Jobs story'' Sunday Times We all think we know who Steve Jobs was, what made him tick, and what made him succeed. Yet the single most important question about him has never been answered. The young, impulsive, egotistical genius was ousted in the mid-80s from the company he founded, exiled from his own kingdom and cast into the wilderness. Yet he returned a decade later to transform the ailing Apple into the most successful company the world had ever seen. How did this reckless upstart transform himself into a visionary business leader? The first comprehensive study of Jobs'' career following his dismissal from Apple, written with unparalleled access and insight, BECOMING STEVE JOBS offers a startling new portrait of the most important business figure in modern history. The most intimate biography yet of Jobs, written by the journalist who knew him better than any other, BECOMING STEVE JOBS draws on recently discovered interviews that have never before seen the light of day, and answers for the first time the most pressing questions about what made this legendary business leader such a success.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781444762006"},{"type":"ISBN_10","identifier":"1444762001"}],"readingModes":{"text":true,"image":false},"pageCount":453,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"1.11.8.0.preview.2","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=5ZopBQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=5ZopBQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=5ZopBQAAQBAJ&printsec=frontcover&dq=Steve+Jobs&hl=&as_pt=BOOKS&cd=4&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=5ZopBQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=5ZopBQAAQBAJ"}'),
('G6Wz0QEACAAJ', '{"title":"The Zen of Steve Jobs","authors":["Caleb Melby","Forbes LLC"],"publisher":"Wiley","publishedDate":"2012","description":"An illustrated depiction of Steve Jobs'' friendship with Zen Buddhist Kobun Chino Otogawa and the impact it had on Jobs'' career Apple cofounder Steve Jobs (1955-2011) had such an enormous impact on so many people that his life often took on aspects of myth. But much of his success was due to collaboration with designers, engineers and thinkers. The Zen of Steve Jobs tells the story of Jobs'' relationship with one such person: Kobun Chino Otogawa. Kobun was a Zen Buddhist priest who emigrated to the U.S. from Japan in the early 1970s. He was an innovator, lacked appreciation for rules and was passionate about art and design. Kobun was to Buddhism as Jobs was to the computer business: a renegade and maverick. It wasn''t long before the two became friends--a relationship that was not built to last. This graphic book is a reimagining of that friendship. The story moves back and forward in time, from the 1970s to 2011, but centers on the period after Jobs'' exile from Apple in 1985 when he took up intensive study with Kobun. Their time together was integral to the big leaps that Apple took later on with its product design and business strategy. Told using stripped down dialogue and bold calligraphic panels, The Zen of Steve Jobs explores how Jobs might have honed his design aesthetic via Eastern religion before choosing to identify only what he needs and leave the rest behind.","industryIdentifiers":[{"type":"ISBN_10","identifier":"1118295293"},{"type":"ISBN_13","identifier":"9781118295298"}],"readingModes":{"text":false,"image":false},"pageCount":0,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"preview-1.0.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=G6Wz0QEACAAJ&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=G6Wz0QEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=G6Wz0QEACAAJ&dq=Steve+Jobs&hl=&as_pt=BOOKS&cd=18&source=gbs_api","infoLink":"http://books.google.com.br/books?id=G6Wz0QEACAAJ&dq=Steve+Jobs&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/The_Zen_of_Steve_Jobs.html?hl=&id=G6Wz0QEACAAJ"}'),
('aruZoAEACAAJ', '{"title":"Inside the Mind of Albert Einstein","authors":["Daniel Willey","Albert Einstein"],"publisher":"Createspace Independent Publishing Platform","publishedDate":"2014-04-16","description":"Albert Einstein has been hailed as one of the greatest minds to ever exist on our planet. He was a German-born theoretical physicist. He developed the general theory of relativity, one of the two pillars of modern physics. He received the 1921 Nobel Prize in Physics for \"his services to theoretical physics, and especially for his discovery of the law of the photoelectric effect. Einstein was visiting the United States when Adolf Hitler came to power and did not go back to Germany, where he had been a professor. This book contains a collection of his thoughts, teachings, & quotes.","industryIdentifiers":[{"type":"ISBN_10","identifier":"1499163509"},{"type":"ISBN_13","identifier":"9781499163506"}],"readingModes":{"text":false,"image":false},"pageCount":64,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"preview-1.0.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=aruZoAEACAAJ&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=aruZoAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=aruZoAEACAAJ&dq=Albert+Einstein&hl=&as_pt=BOOKS&cd=5&source=gbs_api","infoLink":"http://books.google.com.br/books?id=aruZoAEACAAJ&dq=Albert+Einstein&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Inside_the_Mind_of_Albert_Einstein.html?hl=&id=aruZoAEACAAJ"}'),
('Kmm0foYfvQAC', '{"title":"Albert Einstein","subtitle":"A Biography","authors":["Albrecht Fölsing"],"publisher":"Penguin (Non-Classics)","publishedDate":"1998","description":"In a book that is both an engaging portrait of a genius and a distillation of scientific thought, Folsing sheds light on Einstein''s development and the complexity of his being. of photos.","industryIdentifiers":[{"type":"ISBN_10","identifier":"0140237194"},{"type":"ISBN_13","identifier":"9780140237191"}],"readingModes":{"text":false,"image":false},"pageCount":932,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.5.1.0.preview.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=Kmm0foYfvQAC&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=Kmm0foYfvQAC&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=Kmm0foYfvQAC&q=Albert+Einstein&dq=Albert+Einstein&hl=&as_pt=BOOKS&cd=20&source=gbs_api","infoLink":"http://books.google.com.br/books?id=Kmm0foYfvQAC&dq=Albert+Einstein&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Albert_Einstein.html?hl=&id=Kmm0foYfvQAC"}'),
('PZIsP34tQiYC', '{"title":"Nelson Mandela By Himself","subtitle":"The Authorised Book of Quotations","authors":["Nelson Mandela"],"publisher":"Pan Macmillan","publishedDate":"2011-11-04","description":"Nelson Mandela: By Himself is the definitive book of quotations from one of the great leaders of our time. This collection - gathered from privileged authorised access to Mandela''s vast personal archive of private papers, speeches, correspondence and audio recordings - features nearly 2,000 quotations spanning over 60 years, many previously unpublished. Mandela''s inspirational quotations are organised into over 300 categories for easy reference, including such aspects as what defines greatness in ''Character'', ''Courage'' and ''Optimism'', while we learn from the great man the essence of democracy, freedom and struggle in the categories ''Democracy'', ''History'', ''Racism'', ''Reconciliation'' and ''Unity''. Nelson Mandela: By Himself is the first, and only, authorised and authenticated collection of quotations by one of the world''s most admired individuals.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9780230763258"},{"type":"ISBN_10","identifier":"0230763251"}],"readingModes":{"text":true,"image":false},"pageCount":300,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.9.10.0.preview.2","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=PZIsP34tQiYC&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=PZIsP34tQiYC&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=PZIsP34tQiYC&dq=Nelson+Mandela&hl=&as_pt=BOOKS&cd=5&source=gbs_api","infoLink":"http://books.google.com.br/books?id=PZIsP34tQiYC&dq=Nelson+Mandela&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Nelson_Mandela_By_Himself.html?hl=&id=PZIsP34tQiYC"}'),
('RL9zCgAAQBAJ', '{"title":"Mandela","subtitle":"The Life of Nelson Mandela","authors":["Rod Green"],"publisher":"Hachette UK","publishedDate":"2013-12-06","description":"There can''t be many people who have never heard of Nelson Mandela. His has become a household name, a name respected by everyone everywhere, from grandmothers to schoolchildren. Not so many people would recognise his other names, and he is a man who has been known by many names throughout his life. Nelson Rolihlahla Dalibhunga Mandela came from what most people would regard as a poor background, yet his family were aristocrats among the Xhosa people of the Transkei in South Africa. From the time he was a boy he was destined, as his father before him had been, to become an advisor at the court of the Xhosa king, but no one could have predicted that young Rolihlahla would one day become an outlaw known as ''The Black Pimpernel'' or a statesman of international standing - President Mandela. This is a fully illustrated life story of Nelson Mandela with a unique collection of photographs from throughout his life.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9781472104083"},{"type":"ISBN_10","identifier":"1472104080"}],"readingModes":{"text":true,"image":true},"pageCount":194,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"1.2.1.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=RL9zCgAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=RL9zCgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=RL9zCgAAQBAJ&printsec=frontcover&dq=Nelson+Mandela&hl=&as_pt=BOOKS&cd=7&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=RL9zCgAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=RL9zCgAAQBAJ"}'),
('aCAOAQAAMAAJ', '{"title":"Nelson Mandela Speaks","subtitle":"Forging a Democratic, Nonracial South Africa","authors":["Nelson Mandela"],"publisher":"Pathfinder Press (NY)","publishedDate":"1993","description":"This collection contains speeches and interviews Mandela gave in the first three years following his release from prison in 1990.","industryIdentifiers":[{"type":"OTHER","identifier":"UOM:49015001488569"}],"readingModes":{"text":false,"image":false},"pageCount":342,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.4.1.0.preview.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=aCAOAQAAMAAJ&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=aCAOAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=aCAOAQAAMAAJ&q=Nelson+Mandela&dq=Nelson+Mandela&hl=&as_pt=BOOKS&cd=13&source=gbs_api","infoLink":"http://books.google.com.br/books?id=aCAOAQAAMAAJ&dq=Nelson+Mandela&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Nelson_Mandela_Speaks.html?hl=&id=aCAOAQAAMAAJ"}'),
('WV2mDwAAQBAJ', '{"title":"Marie Curie: A Life","authors":["Susan Quinn"],"publisher":"Plunkett Lake Press","publishedDate":"2019-07-31","description":"Marie Curie was long idealized as a selfless and dedicated scientist, not entirely of this world. But Quinn''s Marie Curie is, on the contrary, a woman of passion — born in Warsaw under the repressive regime of the Russian czars, outspokenly committed to the cause of a free Poland, deeply in love with her husband Pierre but also, after his tragic death, capable of loving a second time and of standing up against the cruel, xenophobic attacks which resulted from that love. This biography gives a full and lucid account of Marie and Pierre Curie’s scientific discoveries, placing them within the revelatory discoveries of the age. At the same time, it provides a vivid account of Marie Curie’s practical genius: the X-Ray mobiles she created to save French soldiers'' lives during World War I, as well as her remarkable ability to raise funds and create a laboratory that drew researchers to Paris from all over the world. It is a story which transforms Marie Curie from an bloodless icon into a woman of passion and courage. \"Quinn''s portrait of Curie is rich and captivating. Quinn strives to peel back... layers of myth and idealization that have grown up around the physicist... She succeeds beautifully. Quinn has written a worthy successor to her previous work, the award-winning biography of American psychiatrist Karen Horney.\" — Washington Post Book World (page 1) \"A touching, three-dimensional portrait of the Polish-born scientist and two-time Nobel Prize winner.\" — Kirkus \"I''ve read many biographies of Marie Curie and Susan Quinn''s is magnificent. It''s so complete and so evocative that I can''t imagine anyone coming away from reading it without feeling they actually know Marie Curie.\" — Alan Alda \"Quinn portrays a woman who was both independent and ambitious, in a society that was unprepared for either. The result is a fresh, powerful new biography of a very human Marie Curie... This is an exemplary work, rich in the details and connections that bring a person and her era to life. It is certain to be this generations'' definitive biography of Marie Curie.\" — Science \"Quinn breaks ground in her detailed description, drawn from newly available papers, of Marie''s life after Pierre''s accidental death in 1906. At first so grief-stricken she neglected her two daughters, Irene and Eve, Marie later had a love affair with French scientist Paul Langevin. Because Langevin was married, Marie was vilified by the French press and was almost denied the 1911 Nobel Prize for chemistry.\" —Publishers Weekly \"Susan Quinn''s excellent biography gives a lucid account of Curie''s contribution to our understanding of ''things''... but Quinn also draws on new material to paint a more rounded and attractive picture of Curie the person... For Marie, the enchantment of her science never waned, and it is this enchantment which Quinn''s biography communicates so well.\" — London Observer","readingModes":{"text":true,"image":false},"pageCount":373,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":true,"contentVersion":"0.2.1.0.preview.2","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=WV2mDwAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=WV2mDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=WV2mDwAAQBAJ&printsec=frontcover&dq=Marie+Curie&hl=&as_pt=BOOKS&cd=2&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=WV2mDwAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=WV2mDwAAQBAJ"}'),
('CpHZEQAAQBAJ', '{"title":"Pierre Curie","subtitle":"Su biografía íntima contada por Marie Curie","authors":["Marie Curie"],"publisher":"Plataforma","publishedDate":"2026-06-17","description":"Una vida científica contada desde dentro del propio universo Curie. Este libro no es solo la vida de Pierre Curie. Es una entrada directa al universo en el que se construyeron algunos de los descubrimientos más importantes del siglo XX. A partir de la mirada y el relato de Marie Curie, el relato recorre la trayectoria de Pierre —su formación, su manera de pensar, su trabajo científico— y la sitúa en el contexto real en el que tuvo lugar: años de investigación, condiciones limitadas y una dedicación absoluta al conocimiento. El libro se completa con materiales autobiográficos de Marie Curie que amplían esta perspectiva y permiten entender mejor no solo la figura de Pierre, sino el entorno humano e intelectual en el que ambos desarrollaron su trabajo. Una forma de acercarse a la historia de la ciencia desde dentro, a través de quienes la vivieron.","industryIdentifiers":[{"type":"ISBN_13","identifier":"9791388080395"}],"readingModes":{"text":true,"image":true},"pageCount":196,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"0.1.1.0.preview.3","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=CpHZEQAAQBAJ&printsec=frontcover&img=1&zoom=5&edge=curl&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=CpHZEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api"},"language":"es","previewLink":"http://books.google.com.br/books?id=CpHZEQAAQBAJ&printsec=frontcover&dq=Marie+Curie&hl=&as_pt=BOOKS&cd=6&source=gbs_api","infoLink":"https://play.google.com/store/books/details?id=CpHZEQAAQBAJ&source=gbs_api","canonicalVolumeLink":"https://play.google.com/store/books/details?id=CpHZEQAAQBAJ"}'),
('UqPuAAAAMAAJ', '{"title":"Marie Curie, a Life","authors":["Françoise Giroud"],"publisher":"Holmes & Meier Publishers","publishedDate":"1986","description":"Perhaps the most illustrious women of her era, Marie Curie is well-known for her Nobel Prize-winning research in physics and chemistry and for her discovery with husband Pierre of polonium and radium. Less familiar is the complex character of this renowned woman. While grounding her work in a historical context, the author provides a fresh human perspective on the life of this famous yet enigmatic precursor of today''s atomic scientists.","industryIdentifiers":[{"type":"OTHER","identifier":"UOM:39015013907210"}],"readingModes":{"text":false,"image":false},"pageCount":328,"printType":"BOOK","categories":["Biography & Autobiography"],"maturityRating":"NOT_MATURE","allowAnonLogging":false,"contentVersion":"3.6.3.0.preview.0","panelizationSummary":{"containsEpubBubbles":false,"containsImageBubbles":false},"imageLinks":{"smallThumbnail":"http://books.google.com/books/content?id=UqPuAAAAMAAJ&printsec=frontcover&img=1&zoom=5&source=gbs_api","thumbnail":"http://books.google.com/books/content?id=UqPuAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api"},"language":"en","previewLink":"http://books.google.com.br/books?id=UqPuAAAAMAAJ&q=Marie+Curie&dq=Marie+Curie&hl=&as_pt=BOOKS&cd=9&source=gbs_api","infoLink":"http://books.google.com.br/books?id=UqPuAAAAMAAJ&dq=Marie+Curie&hl=&as_pt=BOOKS&source=gbs_api","canonicalVolumeLink":"https://books.google.com/books/about/Marie_Curie_a_Life.html?hl=&id=UqPuAAAAMAAJ"}');
